using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.Logging;

namespace ResearchAgent;

/// <summary>
/// Provides web search capabilities to the research agent.
/// Uses the Brave Search API (set BRAVE_API_KEY env var) with a
/// fallback to DuckDuckGo Instant Answer for zero-config demo usage.
/// </summary>
public sealed class WebSearchTool(IHttpClientFactory httpClientFactory, ILogger<WebSearchTool> logger)
{
    [Description("Searches the web for information on a given query and returns relevant results. Use this to research a topic.")]
    public async Task<string> SearchWebAsync(
        [Description("The search query to look up on the web")] string query,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Searching the web for: {Query}", query);

        var braveApiKey = Environment.GetEnvironmentVariable("BRAVE_API_KEY");
        if (!string.IsNullOrEmpty(braveApiKey))
        {
            return await SearchWithBraveAsync(query, braveApiKey, cancellationToken);
        }

        return await SearchWithDuckDuckGoAsync(query, cancellationToken);
    }

    private async Task<string> SearchWithBraveAsync(string query, string apiKey, CancellationToken ct)
    {
        var client = httpClientFactory.CreateClient("BraveSearch");
        client.DefaultRequestHeaders.Add("X-Subscription-Token", apiKey);
        client.DefaultRequestHeaders.Add("Accept", "application/json");

        var encoded = Uri.EscapeDataString(query);
        var url = $"https://api.search.brave.com/res/v1/web/search?q={encoded}&count=5";

        var response = await client.GetAsync(url, ct);
        response.EnsureSuccessStatusCode();

        using var doc = await JsonDocument.ParseAsync(await response.Content.ReadAsStreamAsync(ct), cancellationToken: ct);
        var results = doc.RootElement.GetProperty("web").GetProperty("results");

        var output = new List<string>();
        foreach (var result in results.EnumerateArray().Take(5))
        {
            var title = result.GetProperty("title").GetString();
            var snippet = result.GetProperty("description").GetString();
            var resultUrl = result.GetProperty("url").GetString();
            output.Add($"**{title}**\n{snippet}\nSource: {resultUrl}");
        }

        return output.Count > 0
            ? string.Join("\n\n", output)
            : "No results found.";
    }

    private async Task<string> SearchWithDuckDuckGoAsync(string query, CancellationToken ct)
    {
        logger.LogDebug("Using DuckDuckGo Instant Answer fallback");
        var client = httpClientFactory.CreateClient("DuckDuckGo");
        var encoded = Uri.EscapeDataString(query);
        var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_redirect=1";

        var response = await client.GetAsync(url, ct);
        response.EnsureSuccessStatusCode();

        using var doc = await JsonDocument.ParseAsync(await response.Content.ReadAsStreamAsync(ct), cancellationToken: ct);
        var root = doc.RootElement;

        var output = new List<string>();

        var abstractText = root.GetProperty("AbstractText").GetString();
        if (!string.IsNullOrWhiteSpace(abstractText))
        {
            var source = root.GetProperty("AbstractSource").GetString();
            var abstractUrl = root.GetProperty("AbstractURL").GetString();
            output.Add($"**{source}**\n{abstractText}\nSource: {abstractUrl}");
        }

        if (root.TryGetProperty("RelatedTopics", out var topics))
        {
            foreach (var topic in topics.EnumerateArray().Take(5))
            {
                if (topic.TryGetProperty("Text", out var text) &&
                    topic.TryGetProperty("FirstURL", out var topicUrl))
                {
                    output.Add($"{text.GetString()}\nSource: {topicUrl.GetString()}");
                }
            }
        }

        return output.Count > 0
            ? string.Join("\n\n", output)
            : $"No instant answer found for '{query}'. Try rephrasing the search query.";
    }
}

using System.ComponentModel;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.Logging;

namespace ResearchAgent;

/// <summary>
/// Provides note-taking capabilities so the agent can save, list, and
/// retrieve key findings during the research process.
/// </summary>
public sealed class NotesTool(ILogger<NotesTool> logger)
{
    private readonly List<(string Title, string Content)> _notes = [];

    [Description("Saves a research note with a title and content. Use this to record important findings.")]
    public string SaveNote(
        [Description("A short title summarizing the note")] string title,
        [Description("The detailed content of the note")] string content)
    {
        _notes.Add((title, content));
        logger.LogInformation("Note saved: {Title}", title);
        return $"Note #{_notes.Count} saved: \"{title}\"";
    }

    [Description("Lists all saved research notes with their titles. Use this to review what has been recorded so far.")]
    public string ListNotes()
    {
        if (_notes.Count == 0)
        {
            return "No notes saved yet.";
        }

        var lines = _notes.Select((n, i) => $"{i + 1}. {n.Title}");
        return "Saved notes:\n" + string.Join("\n", lines);
    }

    [Description("Retrieves all saved notes with full content. Use this when ready to compile the final summary.")]
    public string GetAllNotes()
    {
        if (_notes.Count == 0)
        {
            return "No notes saved yet.";
        }

        var entries = _notes.Select((n, i) =>
            $"--- Note #{i + 1}: {n.Title} ---\n{n.Content}");
        return string.Join("\n\n", entries);
    }
}

