using System.ComponentModel;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.Logging;

namespace ResearchAgent;

/// <summary>
/// Provides note-taking capabilities so the agent can save, list, and
/// retrieve key findings during the research process.
/// </summary>
public sealed class NotesTool(ILogger<NotesTool> logger)
{
    private readonly List<(string Title, string Content)> _notes = [];

    [Description("Saves a research note with a title and content. Use this to record important findings.")]
    public string SaveNote(
        [Description("A short title summarizing the note")] string title,
        [Description("The detailed content of the note")] string content)
    {
        _notes.Add((title, content));
        logger.LogInformation("Note saved: {Title}", title);
        return $"Note #{_notes.Count} saved: \"{title}\"";
    }

    [Description("Lists all saved research notes with their titles. Use this to review what has been recorded so far.")]
    public string ListNotes()
    {
        if (_notes.Count == 0)
        {
            return "No notes saved yet.";
        }

        var lines = _notes.Select((n, i) => $"{i + 1}. {n.Title}");
        return "Saved notes:\n" + string.Join("\n", lines);
    }

    [Description("Retrieves all saved notes with full content. Use this when ready to compile the final summary.")]
    public string GetAllNotes()
    {
        if (_notes.Count == 0)
        {
            return "No notes saved yet.";
        }

        var entries = _notes.Select((n, i) =>
            $"--- Note #{i + 1}: {n.Title} ---\n{n.Content}");
        return string.Join("\n\n", entries);
    }
}

