using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;
using OpenAI;
using ResearchAgent;

// --- Configuration ---
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable to run this agent.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

// --- DI setup ---
var services = new ServiceCollection();

services.AddLogging(b => b.AddConsole().SetMinimumLevel(LogLevel.Information));
services.AddHttpClient();

services.AddSingleton<NotesTool>();
services.AddSingleton<WebSearchTool>();

services.AddChatClient(builder => builder
    .Use(new OpenAIClient(apiKey).GetChatClient(modelId).AsIChatClient()));

var provider = services.BuildServiceProvider();

// --- Resolve tools ---
var notesTool = provider.GetRequiredService<NotesTool>();
var webSearchTool = provider.GetRequiredService<WebSearchTool>();

var tools = new List<AITool>
{
    AIFunctionFactory.Create(webSearchTool.SearchWebAsync),
    AIFunctionFactory.Create(notesTool.SaveNote),
    AIFunctionFactory.Create(notesTool.ListNotes),
    AIFunctionFactory.Create(notesTool.GetAllNotes),
};

// --- Build the agent ---
var chatClient = provider.GetRequiredService<IChatClient>();
var loggerFactory = provider.GetRequiredService<ILoggerFactory>();

const string instructions = """
    You are a research assistant. When the user gives you a topic:
    1. Search the web multiple times with different queries to gather diverse information.
    2. Save important findings as notes using the note-taking tool.
    3. After gathering enough information, retrieve all your notes and produce a
       well-structured summary with key facts, organized by sub-topic.
    4. Always cite sources in your final summary.
    Be thorough but concise. Aim for 3-5 searches per topic.
    """;

var agent = new ChatClientAgent(chatClient, instructions, "ResearchAgent",
    "Researches topics using web search and note-taking", tools, loggerFactory);

// --- Get topic from user ---
Console.Write("Enter a research topic: ");
var topic = Console.ReadLine()?.Trim();
if (string.IsNullOrWhiteSpace(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");

// --- Run the agent ---
var session = await agent.CreateSessionAsync("research-session");

var runOptions = new ChatClientAgentRunOptions(new ChatOptions
{
    Temperature = 0f,
    MaxOutputTokens = 4096,
});

await foreach (var update in agent.RunStreamingAsync(
    $"Research the following topic and provide a comprehensive summary: {topic}",
    session, runOptions))
{
    if (update.Role == ChatRole.Assistant && !string.IsNullOrEmpty(update.Text))
    {
        Console.Write(update.Text);
    }
}

Console.WriteLine();

